def solve():
    n = int(input())
    a = list(map(int, input().split()))
    likes = [0] * (n + 1)
    dislikes = [0] * (n + 1)

    for i in range(n):
        if a[i] > 0:
            likes[a[i]] += 1
        else:
            dislikes[-a[i]] += 1

    max_likes = []
    min_likes = []

    like_count = sum(likes)
    dislike_count = n - like_count

    for i in range(n):
        if i < like_count:
            max_likes.append(i + 1)
        else:
            max_likes.append(like_count)

        if i < dislike_count:
            min_likes.append(dislike_count - (i + 1))
        else:
            min_likes.append(0)

