def solve():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        p = list(map(int, input().split()))
        q = deque([i + 1 for i in range(n)])
        ans = [-1] * n
        for i in range(m):
            if p[i] <= n:
                q.appendleft(p[i])
                while len(q) > n:
                    q.pop()
            else:
                if p[i] == q[0]:
                    q.popleft()
                else:
                    ans[p[i] - n - 1] = i + 1
        print(*ans)

