def calculate_draws(n, a, b):
    """Calculate the minimum number of draws."""
    diff = abs(a - b)
    if diff % 2 == 0:
        return diff // 2
    else:
        return (diff + 1) // 2

def print_match_scores(n, a, b, draws):
    """Print the match scores with the minimum number of draws."""
    for i in range(n):
        if a > b:
            print(f"{a - draws}:{b}")
            a -= 1
            b += 1
        elif a < b:
            print(f"{a}:{b - draws}")
            a += 1
            b -= 1
        else:
            print("0:0")
            a -= 1
            b -= 1

